-- Synthetic performance fixture. No production data or schema changes.
CREATE TABLE users(id BIGINT UNSIGNED PRIMARY KEY,username VARCHAR(80),full_name VARCHAR(80),email VARCHAR(100),role VARCHAR(20),status VARCHAR(20),deleted_at DATETIME NULL,is_system INT DEFAULT 0,is_online INT DEFAULT 0,current_activity TEXT,avatar_color_gradient TEXT,last_active_at DATETIME,last_seen_at DATETIME,created_at DATETIME);
INSERT INTO users(id,username,full_name,email,role,status,is_system,is_online,last_active_at,created_at) SELECT seq,CONCAT('student',seq),CONCAT('Student ',seq),'synthetic@example.test',IF(seq=900,'facilitator','student'),'active',0,MOD(seq,2),NOW(),NOW() FROM seq_1_to_900;
CREATE TABLE servers(id INT PRIMARY KEY,name VARCHAR(80),slug VARCHAR(80),description TEXT,icon_emoji VARCHAR(20),type VARCHAR(20),status VARCHAR(20),owner_id BIGINT,member_count INT,category VARCHAR(50));
INSERT INTO servers SELECT seq,CONCAT('Server ',seq),CONCAT('server-',seq),'Fixture','S','public','active',900,20,'study' FROM seq_1_to_20;
CREATE TABLE server_members(server_id INT,user_id BIGINT,server_role VARCHAR(20),joined_at DATETIME,PRIMARY KEY(server_id,user_id),KEY idx_user(user_id));
INSERT INTO server_members SELECT s.id,u.id,IF(u.id=900,'owner','member'),DATE_SUB(NOW(),INTERVAL s.id DAY) FROM servers s JOIN users u ON MOD(u.id,3)=MOD(s.id,3) OR u.id=900;
CREATE TABLE channels(id INT PRIMARY KEY,server_id INT,name VARCHAR(80),slug VARCHAR(80),description TEXT,type VARCHAR(20),member_count INT,created_by BIGINT,position INT,is_private INT,is_locked INT,created_at DATETIME,KEY idx_server(server_id));
INSERT INTO channels SELECT seq,1+MOD(seq-1,20),CONCAT('Channel ',seq),CONCAT('channel-',seq),'Fixture','text',30,900,seq,0,0,NOW() FROM seq_1_to_100;
CREATE TABLE messages(id BIGINT PRIMARY KEY,channel_id INT,sender_id BIGINT,content TEXT,is_deleted INT,is_pinned INT DEFAULT 0,created_at DATETIME,updated_at DATETIME,KEY idx_channel(channel_id),KEY idx_sender(sender_id),KEY idx_created(created_at));
INSERT INTO messages SELECT seq,1+MOD(seq,100),1+MOD(seq,900),'Synthetic message',IF(MOD(seq,19)=0,1,0),0,DATE_SUB(CURDATE(),INTERVAL MOD(seq,180) DAY)+INTERVAL MOD(seq,86400) SECOND,NOW() FROM seq_1_to_100000;
-- Date boundary fixtures include midnight, last second, tomorrow, yesterday and NULL.
INSERT INTO messages(id,channel_id,sender_id,content,is_deleted,created_at) VALUES(100001,1,1,'Midnight',0,CURDATE()),(100002,1,1,'End',0,CURDATE()+INTERVAL 1 DAY-INTERVAL 1 SECOND),(100003,1,1,'Tomorrow',0,CURDATE()+INTERVAL 1 DAY),(100004,1,1,'Yesterday',0,CURDATE()-INTERVAL 1 SECOND),(100005,1,1,'Null',0,NULL);
CREATE TABLE direct_messages(id BIGINT PRIMARY KEY,sender_id BIGINT,recipient_id BIGINT,is_read INT,is_deleted INT,created_at DATETIME,KEY idx_sender(sender_id),KEY idx_recipient(recipient_id));
INSERT INTO direct_messages SELECT seq,1+MOD(seq,900),1,MOD(seq,2),0,NOW() FROM seq_1_to_100;
CREATE TABLE message_reads(channel_id INT,user_id BIGINT,last_read_at DATETIME,PRIMARY KEY(channel_id,user_id));
CREATE TABLE study_sessions(id BIGINT PRIMARY KEY,user_id BIGINT,duration_mins INT,started_at DATETIME,KEY idx_user_date(user_id,started_at));
INSERT INTO study_sessions SELECT seq,1+MOD(seq,900),30,DATE_SUB(NOW(),INTERVAL MOD(seq,30) DAY) FROM seq_1_to_9000;
CREATE TABLE study_rooms(id INT PRIMARY KEY,server_id INT,channel_id INT,name VARCHAR(80),description TEXT,icon_emoji VARCHAR(20),max_members INT,status VARCHAR(20));
INSERT INTO study_rooms VALUES(1,1,1,'Room','Fixture','R',10,'active');
CREATE TABLE study_room_sessions(id INT PRIMARY KEY,room_id INT,title VARCHAR(80),description TEXT,scheduled_start DATETIME,scheduled_end DATETIME,status VARCHAR(20),KEY idx_start(scheduled_start));
INSERT INTO study_room_sessions SELECT seq,1,'Session','Fixture',DATE_SUB(NOW(),INTERVAL MOD(seq,100) DAY),NOW(),'scheduled' FROM seq_1_to_10000;
CREATE TABLE study_room_participants(session_id INT,room_id INT,user_id BIGINT,is_active INT);
INSERT INTO study_room_participants VALUES(1,1,1,1);
CREATE TABLE notifications(id INT PRIMARY KEY,recipient_id BIGINT,title TEXT,body TEXT,is_read INT,icon VARCHAR(20),type VARCHAR(30),link_url TEXT,created_at DATETIME,KEY idx_recipient(recipient_id));
INSERT INTO notifications VALUES(1,1,'Fixture','Body',0,'N','message','/synthetic',NOW());
